export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const erased = handler as EventHandler<TaskflowEventType>;
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(erased);
  handlers.set(type, set);
  let attached = true;
  return () => {
    if (!attached) return;
    attached = false;
    // Detach from the set that is live now, not the one captured above: a later
    // subscribe() to the same type has replaced it, and deleting from the stale
    // copy would leave the handler delivering alongside its re-attached twin.
    const current = handlers.get(type);
    if (!current?.has(erased)) return;
    const next: HandlerSet = new Set(current);
    next.delete(erased);
    handlers.set(type, next);
  };
}

